  async function syncCloud(write=false){if(syncing)return;if(!navigator.onLine){syncStatus('Çevrimdışı · cihazda kayıtlı');return;}syncing=true;syncStatus('Eşitleniyor…');
    try{for(let attempt=0;attempt<3;attempt++){const response=await fetch(apiUrl(),{headers:authHeaders(),cache:'no-store',signal:AbortSignal.timeout(15000)});if(!response.ok)throw new Error('GitHub '+response.status);const data=await response.json(),remote=decodeCloud(data.content);if(Array.isArray(remote)&&!localStorage.getItem('cepte_not_v4_backup'))localStorage.setItem('cepte_not_v4_backup',JSON.stringify(remote));const merged=mergeCloud(remote),old=state;state=merged;if(!store()){state=old;throw new Error('Yerel kayıt');}render();
        if(write||dirty){const payload=clone(state);payload.notes.forEach(n=>n.attachments=[]);const snapshot=JSON.stringify(state);const put=await fetch(apiUrl(),{method:'PUT',headers:authHeaders(),signal:AbortSignal.timeout(20000),body:JSON.stringify({message:'Update via Cepte Not v5',content:encodeCloud(payload),sha:data.sha})});if(put.status===409||put.status===422){continue;}if(!put.ok)throw new Error('GitHub '+put.status);dirty=JSON.stringify(state)!==snapshot;try{localStorage.setItem('cepte_not_sync_pending',String(dirty));}catch{}if(dirty)queueSync();}
        syncStatus('Güncel · Bulut');return;}
      throw new Error('Eşitleme çakışması');
    }catch(e){console.error('Bulut eşitlemesi başarısız',e.message);syncStatus('Cihazda kayıtlı · buluta erişilemiyor',true);}
    finally{syncing=false;}}
