  let touchDrag=null;document.addEventListener('pointerdown',e=>{if(e.pointerType!=='touch'||e.target.closest('button,input,select,a'))return;const card=e.target.closest('.kanban [data-card-id]');if(!card)return;touchDrag={id:card.dataset.cardId,x:e.clientX,y:e.clientY,ready:false,timer:setTimeout(()=>{if(touchDrag)touchDrag.ready=true;},400)};});
